INSERT INTO items (item_type_id, content, answer_set, word_count, difficulty, cefr_level, status, pool, topic, exam_part_id, exam_order) VALUES
('reading', '{"text": "Tea is one of the most popular drinks in the world. It originally comes from China, where people have been drinking it for thousands of years. Today, tea is grown in many countries, including India, Kenya, and Sri Lanka. There are several types of tea, such as green, black, and herbal. Many people enjoy tea with milk, sugar, or honey."}'::jsonb, '{"exact": "Tea is one of the most popular drinks in the world. It originally comes from China, where people have been drinking it for thousands of years. Today, tea is grown in many countries, including India, Kenya, and Sri Lanka. There are several types of tea, such as green, black, and herbal. Many people enjoy tea with milk, sugar, or honey."}'::jsonb, 62, 0.35, 'A2', 'approved', 'exam', 'general', 'b1000000-0000-4000-8000-000000000011', 1),
('reading', '{"text": "Bicycles are a simple and efficient way to travel short distances. They do not use fuel, so they produce no pollution. Riding a bicycle also helps people stay healthy because it is good exercise. In many cities, special paths are built just for cyclists. Some people use bicycles to commute to work every day instead of driving a car."}'::jsonb, '{"exact": "Bicycles are a simple and efficient way to travel short distances. They do not use fuel, so they produce no pollution. Riding a bicycle also helps people stay healthy because it is good exercise. In many cities, special paths are built just for cyclists. Some people use bicycles to commute to work every day instead of driving a car."}'::jsonb, 63, 0.40, 'B1', 'approved', 'exam', 'general', 'b1000000-0000-4000-8000-000000000011', 2);
