INSERT INTO items (item_type_id, content, answer_set, word_count, difficulty, cefr_level, status, pool, topic, exam_part_id, exam_order) VALUES
('typing', '{"text": "Getting enough sleep is important for good health. Many adults need between seven and nine hours of sleep every night, but busy schedules often make this difficult. Poor sleep can affect memory, mood, and energy levels throughout the day. Experts suggest keeping a regular bedtime, avoiding screens before sleep, and keeping the bedroom dark and quiet. Simple habits like these can make a noticeable difference. Over time, better sleep can improve concentration at work or school, as well as overall physical health. Making small changes to a daily routine is often enough to see real improvement."}'::jsonb, '{"exact": "Getting enough sleep is important for good health. Many adults need between seven and nine hours of sleep every night, but busy schedules often make this difficult. Poor sleep can affect memory, mood, and energy levels throughout the day. Experts suggest keeping a regular bedtime, avoiding screens before sleep, and keeping the bedroom dark and quiet. Simple habits like these can make a noticeable difference. Over time, better sleep can improve concentration at work or school, as well as overall physical health. Making small changes to a daily routine is often enough to see real improvement."}'::jsonb, 96, 0.45, 'B1', 'approved', 'exam', 'health', 'b1000000-0000-4000-8000-000000000015', 1);
