INSERT INTO items (item_type_id, content, answer_set, word_count, difficulty, cefr_level, status, pool, topic, exam_part_id, exam_order) VALUES
('passage_reconstruction', '{"passage": "Sophie forgot her umbrella at home before leaving for work. Halfway there, it started raining heavily. She ducked into a nearby shop to wait out the storm. After twenty minutes, the rain stopped, and she continued her walk, only slightly late."}'::jsonb, '{"key_points": ["Sophie forgot her umbrella", "it started raining heavily", "she waited in a shop", "she continued and arrived only slightly late"]}'::jsonb, 41, 0.50, 'B1', 'approved', 'exam', 'daily-life', 'b1000000-0000-4000-8000-000000000018', 1),
('passage_reconstruction', '{"passage": "Daniel wanted to surprise his sister for her birthday. He secretly planned a small party with her closest friends and decorated the living room. When she arrived home, everyone shouted surprise. She was so happy that she cried tears of joy and thanked everyone warmly."}'::jsonb, '{"key_points": ["Daniel planned a surprise party for his sister", "he decorated the living room", "everyone shouted surprise when she arrived", "she was happy and thanked everyone"]}'::jsonb, 45, 0.52, 'B1', 'approved', 'exam', 'family', 'b1000000-0000-4000-8000-000000000018', 2),
('passage_reconstruction', '{"passage": "A small bakery in town started selling bread very early each morning. Soon, lines formed outside before sunrise. The owner decided to open an hour earlier to meet demand. Customers were delighted, and the bakery''s reputation grew quickly across the neighborhood."}'::jsonb, '{"key_points": ["the bakery started selling bread early", "lines formed before sunrise", "the owner opened earlier to meet demand", "the bakery became well known in the neighborhood"]}'::jsonb, 42, 0.55, 'B2', 'approved', 'exam', 'community', 'b1000000-0000-4000-8000-000000000018', 3);
INSERT INTO items (item_type_id, content, answer_set, word_count, difficulty, cefr_level, status, pool, topic, exam_part_id, exam_order) VALUES
('summary_and_opinion', '{"passage": "More companies now allow employees to work from home instead of commuting to an office every day. This change started becoming common a few years ago, and many workers have strong opinions about it. Some people believe working from home is the better choice, while others prefer the traditional office environment.\n\nEmployees who work from home often save a great deal of time because they do not need to travel. This extra time can be used for exercise, family, or rest. Working from home also gives people more control over their schedule. They can arrange their day around personal tasks, as long as their work gets done. In addition, many people feel more comfortable and relaxed in their own space, which can help them focus better on certain tasks.\n\nOn the other hand, working in an office has its own advantages. Employees can speak with coworkers in person, which often makes teamwork easier and faster. Being in an office also helps some people separate their work life from their home life. Without a clear line between the two, some workers find it difficult to stop working at the end of the day. Offices can also provide equipment and resources that are not always available at home.\n\nBoth working from home and working in an office have real benefits. The best choice often depends on a person''s job, personality, and home situation. Companies that offer a choice between the two may help employees feel more satisfied and productive overall."}'::jsonb, '{"key_points": ["more companies now allow remote work", "working from home saves time and gives more control over schedule", "offices make teamwork and separating work/home life easier", "the best choice depends on the person and job"]}'::jsonb, 285, 0.60, 'B2', 'approved', 'exam', 'workplace', 'b1000000-0000-4000-8000-000000000019', 1);
